//! ProcFS File Template and Operations.
//!
//! A procfs file is a *view* over live kernel state: its content exists only
//! while the file is open and is regenerated by [`ProcFileOps::
//! generate_content`] at each `open(2)`. This mirrors the seq-file model of
//! Linux (`fs/seq_file.c`), where proc handlers simply produce their output
//! into a buffer without any persistent storage behind the inode.
//!
//! Concrete procfs files are plain structs (e.g. [`super::super::meminfo::
//! MemInfoFileOps`]) implementing [`ProcFileOps`]; [`ProcFileNodeOps`] turns
//! such a struct into a full VFS node.

use alloc::{boxed::Box, sync::Arc, vec::Vec};

use crate::{
    fs::{
        template::{BufFileOps, WriteHook, ro_file_mode, rw_file_mode},
        vfs::{FileOps, INode, INodeAttr, NodeOps, OpenFlags},
    },
    uapi::errno::Result,
};

/// Content operations for a virtual procfs file.
///
/// Implementations generate the file's textual (or binary) content from
/// kernel state; there is no per-file storage anywhere.
pub trait ProcFileOps: Send + Sync + 'static {
    /// Produces the full content of the file, called once per `open(2)`.
    fn generate_content(&self) -> Vec<u8>;

    /// Handles a write to a writable procfs file (e.g. sysctl tunables).
    ///
    /// The default rejects writes as the overwhelming majority of procfs
    /// files are read-only reporting surfaces.
    fn write_content(&self, _data: &[u8]) -> Result<()> {
        crate::return_errno!(EROFS, "procfs file is read-only");
    }
}

/// Node operations adapter that exposes a [`ProcFileOps`] as a procfs file.
///
/// The inner generator is kept in an [`alloc::sync::Arc`] so that writable
/// files can route writes back into `write_content` independent of the node
/// lifetime.
pub struct ProcFileNodeOps<T: ProcFileOps> {
    inner: Arc<T>,
    writable: bool,
}

/// Convenience alias matching the Asterinas/Silica `ProcFile<T>` style.
pub type ProcFile<T> = ProcFileNodeOps<T>;

impl<T: ProcFileOps> ProcFileNodeOps<T> {
    /// Creates read-only node operations around `inner`.
    pub fn new(inner: T) -> Self {
        Self {
            inner: Arc::new(inner),
            writable: false,
        }
    }

    /// Creates node operations around `inner` that accept writes.
    pub fn new_writable(inner: T) -> Self {
        Self {
            inner: Arc::new(inner),
            writable: true,
        }
    }
}

impl<T: ProcFileOps> NodeOps for ProcFileNodeOps<T> {
    fn open(&self, flags: OpenFlags) -> Result<Box<dyn FileOps>> {
        if flags.contains(OpenFlags::WRITE) && !self.writable {
            crate::return_errno!(EPERM, "file is read-only");
        }
        let data = self.inner.generate_content();
        if self.writable {
            let inner = Arc::clone(&self.inner);
            let hook: WriteHook = Box::new(move |buf: &[u8]| {
                inner.write_content(buf)?;
                Ok(buf.len())
            });
            Ok(Box::new(BufFileOps::with_write_hook(data, hook)))
        } else {
            Ok(Box::new(BufFileOps::new(data)))
        }
    }

    fn getattr(&self) -> Result<INodeAttr> {
        Ok(INodeAttr {
            size: 0,
            mode: if self.writable {
                rw_file_mode()
            } else {
                ro_file_mode()
            },
            nlink: 1,
            uid: 0,
            gid: 0,
            rdev: 0,
        })
    }
}

/// A trivially-static procfs file whose content is a constant byte string
/// (e.g. `/proc/sys/kernel/ostype`).
pub struct StaticFileOps {
    data: &'static [u8],
}

impl StaticFileOps {
    /// Creates a file that always reports `data`.
    pub fn new(data: &'static [u8]) -> Self {
        Self { data }
    }
}

impl ProcFileOps for StaticFileOps {
    fn generate_content(&self) -> Vec<u8> {
        self.data.to_vec()
    }
}

/// Builds a fully-formed read-only procfs file inode.
pub fn file_node<T: ProcFileOps>(inner: T, ino: usize) -> Arc<INode> {
    Arc::new(INode::new_with_attr(
        Box::new(ProcFileNodeOps::new(inner)),
        ino,
        INodeAttr {
            mode: ro_file_mode(),
            ..Default::default()
        },
    ))
}

/// Builds a fully-formed writable procfs file inode.
pub fn rw_file_node<T: ProcFileOps>(inner: T, ino: usize) -> Arc<INode> {
    Arc::new(INode::new_with_attr(
        Box::new(ProcFileNodeOps::new_writable(inner)),
        ino,
        INodeAttr {
            mode: rw_file_mode(),
            ..Default::default()
        },
    ))
}

/// Builds a fully-formed procfs file inode with constant content.
pub fn static_file_node(data: &'static [u8], ino: usize) -> Arc<INode> {
    file_node(StaticFileOps::new(data), ino)
}
